<script setup lang="ts">
import {useI18n} from 'vue-i18n'
import ReaderInputPreferences from '../../reading/ReaderInputPreferences.vue'
import {useComicState} from '../state'
const {t}=useI18n(),state=useComicState()
</script>
<template><div class="comic-preferences"><div class="comic-preference"><span>{{ t('comic.readMode') }}</span><div><button :aria-pressed="state.preferences.flow==='strip'" @click="state.setPreferences({flow:'strip'})">{{ t('comic.strip') }}</button><button :aria-pressed="state.preferences.flow==='pages'" @click="state.setPreferences({flow:'pages'})">{{ t('comic.pages') }}</button></div></div><div class="comic-preference"><span>{{ t('comic.direction') }}</span><div><button :aria-pressed="state.preferences.direction==='ltr'" @click="state.setPreferences({direction:'ltr'})">{{ t('comic.leftToRight') }}</button><button :aria-pressed="state.preferences.direction==='rtl'" @click="state.setPreferences({direction:'rtl'})">{{ t('comic.rightToLeft') }}</button></div></div><div class="comic-preference comic-brightness"><span>{{ t('novel.brightness') }}</span><input type="range" min="20" max="100" :value="state.preferences.brightness*100" :disabled="state.preferences.systemBrightness" :aria-label="t('novel.brightness')" @input="state.setPreferences({brightness:Number(($event.target as HTMLInputElement).value)/100})"/><button :aria-pressed="state.preferences.systemBrightness" @click="state.setPreferences({systemBrightness:!state.preferences.systemBrightness})">{{ t('novel.followSystem') }}</button></div><ReaderInputPreferences :value="state.preferences" @change="state.setPreferences"/><p>{{ t('comic.gestureHelp') }}</p></div></template>
